    @location(1) aPoint1: vec2<f32>,
    @location(2) aPoint2: vec2<f32>,
    @location(3) aNext: vec2<f32>,
    @location(4) aTravel: f32,
    @location(5) aVertexJoint: f32,
    @location(6) aLineWidth: f32,
    @location(7) aStylePacked: f32,
