  // modules/pixi/PixiLayerDebug.ts
  var STATUS_COLORS = {
    matched: 52292,
    unmatched: 16724787,
    unknown: 10066329
  };
  var JOIN_COLOR = 3381759;

  class PixiLayerDebug extends AbstractPixiLayer {
    _drawnAs;
    constructor(scene) {
      super(scene);
      this.id = "debug";
      this.enabled = false;
      this._drawnAs = new WeakMap;
    }
    reset() {
      super.reset();
      for (const groupID of ["debug-under", "debug-over"]) {
        const groupContainer = this.scene.groups.get(groupID);
        groupContainer.eventMode = "none";
      }
    }
    render(frame, viewport) {
      if (!this.enabled)
        return;
      const context = this.context;
      const conflation = context.systems.conflation;
      const rapid = context.systems.rapid;
      const spatial = context.systems.spatial;
      if (!conflation || !rapid)
        return;
      for (const ds of rapid.datasets.values()) {
        if (!rapid.enabledDatasetIDs.has(ds.id) || !conflation.isEnabled(ds))
          continue;
        for (const item of spatial.getVisibleItems(ds.spatialID)) {
          const d = item.contents;
          const result = conflation.getResult(ds, d);
          if (!result)
            continue;
          const prefix = `${this.layerID}-${ds.id}-${d.id}`;
          result.boxes?.forEach((box, i) => {
            const loc = projWorldToWgs84(box.coord);
            this._renderMarker(`${prefix}-box${i}`, loc, box.status, frame, viewport);
          });
          result.runs?.forEach((run, i) => {
            if (run.startJoin)
              this._renderMarker(`${prefix}-run${i}-start`, projWorldToWgs84(run.startJoin.coord), "join", frame, viewport);
            if (run.endJoin)
              this._renderMarker(`${prefix}-run${i}-end`, projWorldToWgs84(run.endJoin.coord), "join", frame, viewport);
          });
        }
      }
    }
    _renderMarker(featureID, loc, kind, frame, viewport) {
      let feature = this.features.get(featureID);
      if (!feature) {
        feature = new PixiFeaturePoint(this, featureID);
        feature.allowInteraction = false;
        feature.parentContainer = this.scene.groups.get("debug-over");
      }
      const drawnAs = `${kind}@${loc[0]},${loc[1]}`;
      if (this._drawnAs.get(feature) !== drawnAs) {
        this._drawnAs.set(feature, drawnAs);
        const part = new GeometryPart(this.context);
        part.setData({ type: "Point", coordinates: loc });
        feature.geometry = part;
        const isJoin = kind === "join";
        feature.style = {
          marker: {
            color: isJoin ? JOIN_COLOR : STATUS_COLORS[kind],
            image: isJoin ? "mediumCircle" : "smallCircle"
          }
        };
      }
      if (feature.dirty) {
        feature.update(viewport);
      }
      this.retainFeature(feature, frame);
    }
  }

  // modules/pixi/PixiLayerEditBlocks.ts
  var MINZOOM = 4;

  class PixiLayerEditBlocks extends AbstractPixiLayer {
    constructor(scene) {
      super(scene);
      this.id = "edit-blocks";
      this.enabled = true;
    }
    get enabled() {
      return true;
    }
    set enabled(val) {
      this._enabled = true;
    }
    render(frame, viewport) {
      const context = this.context;
      const l10n = context.systems.l10n;
      const locations = context.systems.locations;
      const mapViewport = context.viewport;
      const viewZoom = mapViewport.transform.zoom;
      if (!locations)
        return;
      let blocks = [];
      if (viewZoom >= MINZOOM) {
        blocks = locations.getBlocks(mapViewport.visibleExtent());
        this.renderEditBlocks(frame, viewport, blocks);
      }
      const $explanationRow = context.container().select(".main-content > .map-footer").selectAll(".api-status.blocks").data(blocks, (d) => d.id);
      $explanationRow.exit().remove();
      const $$explanationRow = $explanationRow.enter().insert("div", ".api-status").attr("class", "api-status blocks error");
      $$explanationRow.append("span").attr("class", "explanation-item").text((d) => d.properties.text);
      $$explanationRow.append("a").attr("target", "_blank").attr("href", (d) => d.properties.url).text(l10n?.t("rapid_catalog.more_info") || "More Info");
    }
    renderEditBlocks(frame, viewport, blocks) {
      const parentContainer = this.scene.groups.get("blocks");
      if (!parentContainer)
        return;
      const blockStyle = {
        fill: { pattern: "construction", color: 0, opacity: 0.7, type: "full" }
      };
      for (const d of blocks) {
        const dataID = d.id;
        const parts = d.geoms.parts;
        for (let i = 0;i < parts.length; ++i) {
          const part = parts[i];
          if (!part.world || part.type !== "Polygon")
            continue;
          const featureID = `${this.layerID}-${dataID}-${i}`;
          let feature = this.features.get(featureID);
          if (!feature) {
            feature = new PixiFeaturePolygon(this, featureID);
            feature.allowInteraction = false;
            feature.style = blockStyle;
            feature.parentContainer = parentContainer;
            feature.container.cursor = "not-allowed";
          }
          if (feature.data !== d || feature.geometry !== part) {
            feature.geometry = part;
            feature.data = d;
          }
          feature.update(viewport);
          this.retainFeature(feature, frame);
        }
      }
    }
  }

  // modules/pixi/PixiLayerKartaPhotos.ts
  var MINZOOM2 = 12;
