          continue;
        if (!localCoords || localCoords.length < 2)
          continue;
        if (!feature.container.visible || !feature.container.renderable)
          continue;
        const labelCoords = new Array(localCoords.length);
        let minX = Infinity;
        let minY = Infinity;
        let maxX = -Infinity;
        let maxY = -Infinity;
        const position = feature.container.position;
        for (let i = 0;i < localCoords.length; i++) {
          const p = localCoords[i];
          world.set(p[0] + position.x, p[1] + position.y);
          origin.toGlobal(world, temp);
          labelCoords[i] = [temp.x - labelOffset.x, temp.y - labelOffset.y];
          if (temp.x < minX)
            minX = temp.x;
          if (temp.x > maxX)
            maxX = temp.x;
          if (temp.y < minY)
            minY = temp.y;
          if (temp.y > maxY)
            maxY = temp.y;
        }
        const lineWidth = Math.max(0, 2 * feature.hitReach - 10);
        if (maxX - minX + lineWidth < 40 && maxY - minY + lineWidth < 40)
          continue;
