      this.createTexture("symbol", "oneway", oneway);
      this.createTexture("symbol", "twoway", twoway);
      this.createTexture("symbol", "sided", sided);
      const lowresSquare = new Graphics().rect(-5, -5, 10, 10).fill({ color: 16777215, alpha: 0.6 }).stroke({ color: 16777215, width: 1 });
      const lowresEll = new Graphics().poly([-5, -5, 5, -5, 5, 5, 1, 5, 1, 1, -5, 1, -5, -5]).fill({ color: 16777215, alpha: 0.6 }).stroke({ color: 16777215, width: 1 });
      const lowresCircle = new Graphics().circle(0, 0, 5).fill({ color: 16777215, alpha: 0.6 }).stroke({ color: 16777215, width: 1 });
