      this.createTexture("symbol", "lowres-ell", lowresEll);
      this.createTexture("symbol", "lowres-circle", lowresCircle);
      const lowresUnfilledSquare = new Graphics().rect(-5, -5, 10, 10).stroke({ color: 16777215, width: 1 });
      const lowresUnfilledEll = new Graphics().poly([-5, -5, 5, -5, 5, 5, 1, 5, 1, 1, -5, 1, -5, -5]).stroke({ color: 16777215, width: 1 });
