      $$title.append("button").attr("class", "close").on("click", this.toggle).call(uiIcon("#rapid-icon-close"));
      $$wrap.append("div").attr("class", (d) => `card-content card-content-${d}`);
      this.$wrap = $wrap = $wrap.merge($$wrap);
      $wrap.selectAll("h3").text(l10n.t("info_panels.background.title"));
      const $content = $wrap.selectAll(".card-content");
      const source = imagery.baseLayerSource();
