      $$nudge.append("div").attr("class", "nudge-inner-rect").append("input").attr("type", "text").on("change", this._inputOffset);
      $$nudgeWrap.append("div").selectAll("button").data(DIRECTIONS).enter().append("button").attr("class", (d) => `${d[0]} nudge`).attr("tabindex", -1).on("click", (e, d) => this._nudge(d[1]));
