  // modules/ui/sections/UiSectionOverlayList.ts
  class UiSectionOverlayList extends AbstractUiSection {
    _overlayList;
    rerender;
    constructor(context) {
      super(context, "overlay-list");
      const gfx = context.systems.gfx;
      const imagery = context.systems.imagery;
      this._overlayList = select(null);
      this._drawListItems = this._drawListItems.bind(this);
      this._setTooltips = this._setTooltips.bind(this);
      this._updateLayerSelections = this._updateLayerSelections.bind(this);
      this._chooseOverlay = this._chooseOverlay.bind(this);
      this._onMapDraw = this._onMapDraw.bind(this);
      this._deferredOnMapDraw = this._deferredOnMapDraw.bind(this);
      this.rerender = () => this.renderInner();
      imagery.on("imagerychange", this.rerender);
      gfx.on("draw", this._deferredOnMapDraw);
    }
    label() {
      const l10n = this.context.systems.l10n;
      return l10n.t("background.overlays");
    }
    _isOverlay(d) {
      return !!d.props.overlay;
    }
    renderDisclosureContent($selection) {
      const $container = $selection.selectAll(".layer-overlay-list").data([0]);
      this._overlayList = $container.enter().append("ul").attr("class", "layer-list layer-overlay-list").merge($container);
      this._overlayList.call(this._drawListItems);
    }
    _setTooltips($selection) {
      const context = this.context;
      $selection.each((d, i, nodes) => {
        const item = select(nodes[i]).select("label");
        const span = item.select("span");
        const placement = i < nodes.length / 2 ? "bottom" : "top";
        const isOverflowing = span.property("clientWidth") !== span.property("scrollWidth");
        item.call(new UiTooltip(context).destroyAny);
        if (d.description || isOverflowing) {
          item.call(new UiTooltip(context).placement(placement).title(d.description || d.name).attach);
        }
      });
    }
    _updateLayerSelections($selection) {
      const imagery = this.context.systems.imagery;
      const isActive = (d) => imagery.showsLayer(d);
      $selection.selectAll("li").classed("active", isActive).call(this._setTooltips).selectAll("input").property("checked", isActive);
    }
    _drawListItems($selection) {
      const imagery = this.context.systems.imagery;
      const sources = imagery.visibleSources().filter((d) => this._isOverlay(d));
      const sortSources = (a, b) => {
        return descending(a.area, b.area) || ascending(a.name, b.name) || 0;
      };
      const $layerLinks = $selection.selectAll("li").data(sources, (d) => d.name);
      $layerLinks.exit().remove();
      const $$layerLinks = $layerLinks.enter().append("li");
      const $$label = $$layerLinks.append("label");
      $$label.append("input").attr("type", "checkbox").attr("name", "layers").on("change", this._chooseOverlay);
      $$label.append("span").text((d) => d.name);
      $selection.selectAll("li").sort(sortSources);
      $selection.call(this._updateLayerSelections);
    }
    _chooseOverlay(e, d) {
      const imagery = this.context.systems.imagery;
      e.preventDefault();
      imagery.toggleOverlayLayer(d);
      this._overlayList.call(this._updateLayerSelections);
    }
    _onMapDraw() {
      const scheduler = this.context.systems.scheduler;
      if (scheduler) {
        scheduler.scheduleIdleTask(() => this.renderInner()).catch((err) => {
          if (err?.name === "AbortError")
            return;
          console.error(err);
        });
      } else {
        this.renderInner();
      }
    }
    _deferredOnMapDraw() {
      const scheduler = this.context.systems.scheduler;
      scheduler?.throttle("OverlayList-mapDraw", this._onMapDraw, { ms: 1000 });
    }
  }

