      $choiceWrap.selectAll("button").classed("secondary disabled", isDisabled);
      $choiceWrap.selectAll(".choice-label").text(l10n.t(d.labelStringID));
      $choiceWrap.selectAll(".tag-reference-button").attr("title", l10n.t("icons.information"));
      let title = null;
      let shortcut = null;
      if (d.key === "accept") {
        if (isDisabled) {
          title = l10n.t("rapid_inspector.option_accept.disabled", { n: ACCEPT_FEATURES_LIMIT });
          shortcut = "";
        } else {
          title = l10n.t("rapid_inspector.option_accept.tooltip");
          shortcut = l10n.t("shortcuts.command.accept_feature.key");
        }
      } else if (d.key === "ignore") {
        title = l10n.t("rapid_inspector.option_ignore.tooltip");
        shortcut = l10n.t("shortcuts.command.ignore_feature.key");
      }
      d.tooltip.title(title).shortcut(shortcut);
      let $tagReference = $choice.selectAll(".tag-reference-body").data([d]);
      const $$tagReference = $tagReference.enter().append("div").attr("class", "tag-reference-body");
      $tagReference = $tagReference.merge($$tagReference);
