      const eventManager = gfx.eventManager;
      const continueNodeID = options.continueNodeID;
      const continueWayID = options.continueWayID;
      const continueNode = continueNodeID && graph.hasEntity(continueNodeID);
      const continueWay = continueWayID && graph.hasEntity(continueWayID);
      if (continueNode || continueWay) {
        if (!(continueNode instanceof OsmNode))
          return false;
        if (!(continueWay instanceof OsmWay))
          return false;
        if (DEBUG5) {
          console.log(`DrawLineMode: entering, continuing line ${continueWay.id}`);
        }
      } else {
        if (DEBUG5) {
          console.log("DrawLineMode: entering");
        }
      }
      this._active = true;
      this.drawWayID = null;
      this.drawNodeID = null;
      this.lastNodeID = null;
      this.firstNodeID = null;
      this._insertIndex = undefined;
      this._lastScreen = null;
      this._selectedIDs = [];
      eventManager.setCursor("crosshair");
      context.enableBehaviors(["hover", "draw", "mapInteraction", "mapNudge"]);
      context.behaviors.hover.on("hoverchange", this._hover);
      context.behaviors.draw.on("move", this._move).on("click", this._click).on("finish", this._finish).on("cancel", this._cancel);
      context.behaviors.mapNudge.on("nudge", this._nudge);
