      context.behaviors.hover.off("hoverchange", this._hover);
      context.behaviors.draw.off("move", this._move).off("click", this._click).off("finish", this._finish).off("cancel", this._cancel);
      context.behaviors.mapNudge.off("nudge", this._nudge);
      editor.off("historyjump", this._restoreSnapshot);
      editor.beginTransaction();
