  // modules/operations/SplitOperation.ts
  class SplitOperation extends AbstractOperation {
    _vertexIDs;
    _vertexMulti;
    _wayIDs;
    _isAvailable;
    _action;
    _geometry;
    _splittable;
    _waysMulti;
    constructor(context, selectedIDs) {
      super(context, selectedIDs);
      const editor = context.systems.editor;
      const l10n = context.systems.l10n;
      const graph = editor.staging.graph;
      const entities = selectedIDs.map((entityID) => graph.hasEntity(entityID)).filter(Boolean);
      const vertices = entities.filter((entity) => entity.type === "node" && entity.geometry(graph) === "vertex");
      const ways = entities.filter((entity) => entity.type === "way");
      this._vertexIDs = vertices.map((entity) => entity.id);
      this._vertexMulti = this._vertexIDs.length === 1 ? "single" : "multiple";
      this._wayIDs = ways.map((entity) => entity.id);
      this._isAvailable = vertices.length > 0 && vertices.length + ways.length === selectedIDs.length;
      this._action = actionSplit(this._vertexIDs);
      this._geometry = "feature";
      this._splittable = [];
      this._waysMulti = "single";
      if (this._isAvailable) {
        if (this._wayIDs.length) {
          this._action.limitWays(this._wayIDs);
        }
        this._splittable = this._action.ways(graph);
        const geometries = new Set;
        for (const way of this._splittable) {
          geometries.add(way.geometry(graph));
        }
        if (geometries.size === 1) {
          this._geometry = Array.from(geometries)[0];
        }
        this._waysMulti = this._splittable.length === 1 ? "single" : "multiple";
      }
      this.id = "split";
      this.keys = [l10n.t("shortcuts.command.split.key")];
      this.title = l10n.t("operations.split.title");
      this.behavior = new KeyOperationBehavior(context, this);
    }
    run() {
      const context = this.context;
      const editor = context.systems.editor;
      const label = this.editLabel();
      const difference = editor.perform(this._action);
      const idsToSelect = this._vertexIDs.slice();
      if (difference) {
        for (const [entityID, change] of difference.changes) {
          const entity = change.head;
          if (entity && entity.type === "way") {
            idsToSelect.push(entityID);
          }
        }
      }
      editor.commit({ ...label, selectionAfter: idsToSelect });
      context.enter("select", { selection: idsToSelect });
    }
    relatedEntityIds() {
      return this._splittable.map((way) => way.id);
    }
    available() {
      return this._isAvailable;
    }
    disabled() {
      const context = this.context;
      const editor = context.systems.editor;
      const graph = editor.staging.graph;
      const disabledReason = this._action.disabled?.(graph);
      if (disabledReason) {
        return disabledReason;
      } else if (this.selectedIDs.some(context.hasHiddenConnections)) {
        return "connected_to_hidden";
      }
      return false;
    }
    tooltip() {
      const l10n = this.context.systems.l10n;
      const disabledReason = this.disabled();
      return disabledReason ? l10n.t(`operations.split.${disabledReason}`) : l10n.t(`operations.split.description.${this._geometry}.${this._waysMulti}.${this._vertexMulti}_node`);
    }
    editLabel() {
      return { stringID: `operations.split.annotation.${this._geometry}`, stringParams: { n: this._splittable.length } };
    }
  }

  // modules/operations/StraightenOperation.ts
  class StraightenOperation extends AbstractOperation {
    _entities;
    _isNew;
    _ways;
    _wayIDs;
    _nodes;
    _nodeIDs;
    _coords;
    _extent;
    _geometry;
    _action;
    constructor(context, selectedIDs) {
      super(context, selectedIDs);
      const editor = context.systems.editor;
      const l10n = context.systems.l10n;
      const graph = editor.staging.graph;
      this._entities = selectedIDs.map((entityID) => graph.hasEntity(entityID)).filter(Boolean);
      this._isNew = this._entities.every((entity) => entity.isNew());
      this._ways = this._entities.filter((entity) => entity.type === "way");
      this._wayIDs = this._ways.map((entity) => entity.id);
      this._nodes = this._entities.filter((entity) => entity.type === "node");
      this._nodeIDs = this._nodes.map((entity) => entity.id);
      this._coords = utilGetAllNodes(selectedIDs, graph).map((node) => node.loc);
      this._extent = utilTotalExtent(selectedIDs, graph);
      this._action = this._chooseAction();
      this.id = "straighten";
      this.keys = [l10n.t("shortcuts.command.straighten.key")];
      this.title = l10n.t("operations.straighten.title");
      this.behavior = new KeyOperationBehavior(context, this);
    }
    run() {
      const editor = this.context.systems.editor;
      const action = this._action;
      if (!action)
        return;
      const label = this.editLabel();
      editor.animateAndCommitAsync(action, { ...label, selectionAfter: this.selectedIDs });
    }
    available() {
      return Boolean(this._action);
    }
    disabled() {
      const context = this.context;
      const editor = context.systems.editor;
      const settings = context.systems.settings;
      const viewport = context.viewport;
      const action = this._action;
      if (!action)
        return false;
      const graph = editor.staging.graph;
      const coords = this._coords;
      const extent = this._extent;
      const isNew = this._isNew;
      const disabledReason = action.disabled?.(graph);
      if (disabledReason) {
        return disabledReason;
      } else if (!isNew && tooLarge()) {
        return "too_large";
      } else if (!isNew && notDownloaded()) {
        return "not_downloaded";
      } else if (this.selectedIDs.some(context.hasHiddenConnections)) {
        return "connected_to_hidden";
      }
      return false;
      function tooLarge() {
        const allowLargeEdits = settings?.get("poweruser.allowLargeEdits") === "true";
        return !allowLargeEdits && extent.percentContainedIn(viewport.visibleExtent()) < 0.8;
      }
      function notDownloaded() {
        if (context.inIntro)
          return false;
        const osm = context.services.osm;
        if (osm) {
          const missing = coords.filter((loc) => !osm.isDataLoaded(loc));
          if (missing.length) {
            missing.forEach((loc) => context.loadTileAtLoc(loc));
            return true;
          }
        }
        return false;
      }
    }
    tooltip() {
      const l10n = this.context.systems.l10n;
      const disabledReason = this.disabled();
      return disabledReason ? l10n.t(`operations.straighten.${disabledReason}`, { n: this._ways.length || this._nodes.length }) : l10n.t(`operations.straighten.description.${this._geometry}` + (this._ways.length === 1 ? "" : "s"));
    }
    editLabel() {
      return {
        stringID: `operations.straighten.annotation.${this._geometry}`,
        stringParams: { n: this._ways.length || this._nodes.length }
      };
    }
    _chooseAction() {
      const editor = this.context.systems.editor;
      const graph = editor.staging.graph;
      const ways = this._ways;
      const nodes = this._nodes;
      const nodeIDs = this._nodeIDs;
      const wayIDs = this._wayIDs;
      if (ways.length === 0 && nodes.length > 2) {
        this._geometry = "point";
        return actionStraightenNodes(nodeIDs);
      } else if (ways.length > 0 && (nodes.length === 0 || nodes.length === 2)) {
        let startNodeIDs = [];
        let endNodeIDs = [];
        for (const entity of this._entities) {
          if (entity.type !== "way")
            continue;
          const way = entity;
          if (way.isClosed())
            return null;
          startNodeIDs.push(way.first());
          endNodeIDs.push(way.last());
        }
        startNodeIDs = startNodeIDs.filter((nodeID) => startNodeIDs.indexOf(nodeID) === startNodeIDs.lastIndexOf(nodeID));
        endNodeIDs = endNodeIDs.filter((nodeID) => endNodeIDs.indexOf(nodeID) === endNodeIDs.lastIndexOf(nodeID));
        if (utilArrayDifference(startNodeIDs, endNodeIDs).length + utilArrayDifference(endNodeIDs, startNodeIDs).length !== 2)
          return null;
        const wayNodeIDs = utilGetAllNodes(wayIDs, graph).map((node) => node.id);
        if (wayNodeIDs.length <= 2)
          return null;
        if (nodeIDs.length === 2 && (wayNodeIDs.indexOf(nodeIDs[0]) === -1 || wayNodeIDs.indexOf(nodeIDs[1]) === -1))
          return null;
        if (nodeIDs.length) {
          this._extent = utilTotalExtent(nodeIDs, graph);
        }
        this._geometry = "line";
        return actionStraightenWay(this.selectedIDs);
      }
      return null;
    }
  }

  // modules/operations/index.ts
  var operations = {
    available: new Map
  };
  operations.available.set("circularize", CircularizeOperation);
  operations.available.set("continue", ContinueOperation);
  operations.available.set("cycle_highway_tag", CycleHighwayTagOperation);
  operations.available.set("copy", CopyOperation);
  operations.available.set("delete", DeleteOperation);
  operations.available.set("disconnect", DisconnectOperation);
  operations.available.set("downgrade", DowngradeOperation);
  operations.available.set("extract", ExtractOperation);
  operations.available.set("merge", MergeOperation);
  operations.available.set("move", MoveOperation);
  operations.available.set("orthogonalize", OrthogonalizeOperation);
  operations.available.set("paste", PasteOperation);
  operations.available.set("reflect-short", ReflectShortOperation);
  operations.available.set("reflect-long", ReflectLongOperation);
  operations.available.set("reverse", ReverseOperation);
  operations.available.set("rotate", RotateOperation);
  operations.available.set("split", SplitOperation);
  operations.available.set("straighten", StraightenOperation);

  // modules/modes/SelectMode.ts
  var DEBUG7 = false;

  class SelectMode extends AbstractMode {
    _selectScope;
    extent;
    _newFeature;
    _focusedParentID;
    _osmIDs;
    _singularDatum;
    _lastSelectedIDs;
    constructor(context) {
      super(context);
      this.id = "select";
      this._selectScope = null;
      this.extent = null;
      this._newFeature = false;
      this._focusedParentID = null;
      this._osmIDs = [];
      this._singularDatum = null;
      this._lastSelectedIDs = [];
      this._keydown = this._keydown.bind(this);
      this._hover = this._hover.bind(this);
      this._merge = this._merge.bind(this);
      this._firstVertex = this._firstVertex.bind(this);
      this._focusNextParent = this._focusNextParent.bind(this);
      this._lastVertex = this._lastVertex.bind(this);
      this._nextVertex = this._nextVertex.bind(this);
      this._previousVertex = this._previousVertex.bind(this);
    }
    enter(options = {}) {
      const context = this.context;
      const editor = context.systems.editor;
      const filters = context.systems.filters;
      const gfx = context.systems.gfx;
      const hover = context.behaviors.hover;
      const keyboard = context.systems.keyboard;
      const locations = context.systems.locations;
      const mapwithai = context.services.mapwithai;
      const spatial = context.systems.spatial;
      const ui = context.systems.ui;
      const urlhash = context.systems.urlhash;
      const graph = editor.staging.graph;
      const scene = gfx.scene;
      const eventManager = gfx.eventManager;
      const selectedIDs = new Set;
      const osmIDs = [];
      for (const dataID of options.selection ?? []) {
        const datum = spatial.getData(dataID);
        if (!datum)
          continue;
        const entityID = osmEntityID(dataID);
        if (entityID) {
          if (selectedIDs.has(entityID))
            continue;
          if (datum.type === "node") {
            const loc = datum.loc;
            if (loc && locations?.isBlockedAt(loc))
              continue;
          }
          osmIDs.push(entityID);
          selectedIDs.add(entityID);
        } else {
          selectedIDs.add(dataID);
        }
      }
      if (!selectedIDs.size)
        return false;
      this._selectedIDs = [...selectedIDs];
      this._osmIDs = osmIDs;
      this._newFeature = options.newFeature ?? false;
      this._focusedParentID = options.focusedParentID ?? null;
      this._lastSelectedIDs = [];
      const isSingular = this._selectedIDs.length === 1;
      this._singularDatum = isSingular && osmIDs.length === 1 ? graph.hasEntity(osmIDs[0]) ?? null : null;
      if (DEBUG7) {
        console.log(`SelectMode: entering, selected ${this._selectedIDs.join(",")}`);
      }
      this._active = true;
      context.enableBehaviors(["hover", "select", "drag", "mapInteraction", "lasso", "paste"]);
      ui?.closeEditMenu();
      this.extent = new Extent;
      for (const d of this.selectedData.values()) {
        let other;
        if (d instanceof OsmEntity) {
          const datasetID = d.props.datasetID;
          const dataGraph = datasetID && mapwithai ? mapwithai.graph(datasetID) : graph;
          other = dataGraph.extent(d);
        } else {
          other = d.extent();
        }
        if (other instanceof Extent) {
          this.extent.extendSelf(other);
        }
      }
      scene.clearClass("select");
      for (const dataID of this._selectedIDs) {
        scene.setClass("select", dataID);
      }
      urlhash.setParam("id", this._selectedIDs.filter(isStableDataID).join(",") || null);
      filters.forceVisible(osmIDs);
      this._setupOperations();
      this._selectScope = keyboard.scope("select");
      this._selectScope.on(["[", "pgup"], this._previousVertex).on(["]", "pgdown"], this._nextVertex).on(["{", utilCmd("⌘["), "home"], this._firstVertex).on(["}", utilCmd("⌘]"), "end"], this._lastVertex).on(["\\", "pause"], this._focusNextParent).enable();
      eventManager.on("keydown", this._keydown);
      editor.on("merge", this._merge);
      hover.on("hoverchange", this._hover);
      this._showSidebar();
      return true;
    }
    exit() {
      if (!this._active)
        return;
      this._active = false;
      const context = this.context;
      const editor = context.systems.editor;
      const filters = context.systems.filters;
      const gfx = context.systems.gfx;
      const hover = context.behaviors.hover;
      const photos = context.systems.photos;
      const ui = context.systems.ui;
      const urlhash = context.systems.urlhash;
      const scene = gfx.scene;
      const eventManager = gfx.eventManager;
      if (DEBUG7) {
        console.log("SelectMode: exiting");
      }
      this.extent = null;
      this._newFeature = false;
      this._osmIDs = [];
      this._singularDatum = null;
      this._selectedIDs = [];
      this._lastSelectedIDs = [];
      for (const operation of this.operations) {
        operation.behavior?.disable();
      }
      this.operations = [];
      scene.clearClass("select");
      ui?.closeEditMenu();
      ui?.Sidebar.hide();
      urlhash.setParam("id", null);
      filters.forceVisible([]);
      photos.selectDetection(null);
      if (this._selectScope) {
        this._selectScope.disable();
        this._selectScope = null;
      }
      editor.off("merge", this._merge);
      eventManager.off("keydown", this._keydown);
      hover.off("hoverchange", this._hover);
    }
    _isAllOsm() {
      return this._osmIDs.length > 0 && this._osmIDs.length === this._selectedIDs.length;
    }
    get movesWithArrowKeys() {
      return this.context.editable() && this._isAllOsm();
    }
    _showSidebar() {
      const context = this.context;
      const gfx = context.systems.gfx;
      const photos = context.systems.photos;
      const ui = context.systems.ui;
      const Sidebar = ui?.Sidebar;
      if (!Sidebar)
        return;
      if (this._isAllOsm()) {
        Sidebar.showInspector(this._osmIDs, this._newFeature);
        return;
      }
      Sidebar.reset();
      if (this._selectedIDs.length > 1) {
        Sidebar.SelectionInspector.dataIDs = this.selectedIDs;
        Sidebar.show(Sidebar.SelectionInspector.render);
        return;
      }
      const datum = this.selectedData.get(this._selectedIDs[0]);
      if (!datum)
        return;
      let sidebarContent = null;
      const datasetID = datum.props?.datasetID ?? "";
      const serviceID = datum.props?.serviceID ?? "";
      const leaveIfSelected = () => {
        if (this._active && this._selectedIDs.includes(datum.dataID)) {
          context.enter("browse");
        }
      };
      if (datum instanceof MarkerData && serviceID === "osm" && datum.type === "note") {
        const noteEditor = new UiNoteEditor(context);
        noteEditor.datum = datum;
        noteEditor.on("change", (saved) => {
          gfx?.immediateRedraw("osm-notes");
          if (saved instanceof MarkerData && saved.id !== datum.id) {
            context.enter("select", { selection: [saved.dataID] });
            return;
          }
          const osm = context.services.osm;
          const d = osm?.getNote(datum.id);
          if (!(d instanceof MarkerData)) {
            leaveIfSelected();
            return;
          }
          noteEditor.datum = d;
          Sidebar?.show(noteEditor.render);
        });
        sidebarContent = noteEditor.render;
      } else if (datum instanceof MarkerData && serviceID === "keepright") {
        const keepRightEditor = new UiKeepRightEditor(context);
        keepRightEditor.datum = datum;
        keepRightEditor.on("change", () => {
          gfx?.immediateRedraw("keepright");
          const keepright = context.services.keepright;
          const d = keepright?.getError(datum.id);
          if (!(d instanceof MarkerData)) {
            leaveIfSelected();
            return;
          }
          keepRightEditor.datum = d;
          Sidebar?.show(keepRightEditor.render);
        });
        sidebarContent = keepRightEditor.render;
      } else if (datum instanceof MarkerData && serviceID === "osmose") {
        const osmoseEditor = new UiOsmoseEditor(context);
        osmoseEditor.datum = datum;
        osmoseEditor.on("change", () => {
          gfx?.immediateRedraw("osmose");
          const osmose = context.services.osmose;
          const d = osmose?.getError(datum.id);
          if (!(d instanceof MarkerData)) {
            leaveIfSelected();
            return;
          }
          osmoseEditor.datum = d;
          Sidebar?.show(osmoseEditor.render);
        });
        sidebarContent = osmoseEditor.render;
      } else if (datum instanceof MarkerData && serviceID === "maproulette") {
        const maprouletteEditor = new UiMapRouletteEditor(context);
        maprouletteEditor.datum = datum;
        const menu = ui?.MapRouletteMenu;
        if (menu)
          menu.datum = datum;
        maprouletteEditor.on("change", () => {
          gfx?.immediateRedraw("maproulette");
          const maproulette = context.services.maproulette;
          const d = maproulette?.getTask(datum.id);
          if (!(d instanceof MarkerData)) {
            leaveIfSelected();
            return;
          }
          maprouletteEditor.datum = d;
          Sidebar?.show(maprouletteEditor.render);
        });
        sidebarContent = maprouletteEditor.render;
      } else if (datum instanceof MarkerData && datum.type === "detection") {
        const detectionInspector = new UiDetectionInspector(context);
        detectionInspector.datum = datum;
        sidebarContent = detectionInspector.render;
        const layerID = splitDataID(datum.dataID)[0];
        photos.selectDetection(layerID, datum.id);
      } else if (datasetID && serviceID === "overture") {
        Sidebar.OvertureInspector.datum = datum;
        sidebarContent = Sidebar.OvertureInspector.render;
      } else if (datasetID && serviceID !== "overture") {
        Sidebar.RapidInspector.datum = datum;
        sidebarContent = Sidebar.RapidInspector.render;
      } else if (datum instanceof GeoJSONData) {
        const dataEditor = new UiDataEditor(context);
        dataEditor.datum = datum;
        sidebarContent = dataEditor.render;
      }
      if (sidebarContent) {
        Sidebar.show(sidebarContent);
      }
    }
    _keydown(e) {
      const context = this.context;
      const editor = context.systems.editor;
      const ui = context.systems.ui;
      const viewport = context.viewport;
      const graph = editor.staging.graph;
      const activeElement = document.activeElement?.tagName ?? "BODY";
      if (!["BODY", "BUTTON"].includes(activeElement))
        return;
      if (document.activeElement?.classList?.contains("preset-list-button"))
        return;
      if (!context.editable())
        return;
      if ((e.altKey || e.metaKey || e.ctrlKey) && e.key === "ArrowUp") {
        e.preventDefault();
        this._selectParentWays();
        return;
      } else if ((e.altKey || e.metaKey || e.ctrlKey) && e.key === "ArrowDown") {
        e.preventDefault();
        this._selectChildNodes();
        return;
      }
      if (!this._isAllOsm())
        return;
      const selectedIDs = this._osmIDs.slice();
      const isSameSelection = utilArrayIdentical(selectedIDs, this._lastSelectedIDs);
      if (!isSameSelection) {
        this._lastSelectedIDs = selectedIDs.slice();
      }
      let operation;
      let action;
      if (e.shiftKey && ["ArrowLeft", "ArrowRight"].includes(e.key)) {
        e.preventDefault();
        const ROT_AMOUNT = 2 * DEG2RAD;
        let delta;
        if (e.key === "ArrowLeft") {
          delta = -ROT_AMOUNT;
        } else if (e.key === "ArrowRight") {
          delta = ROT_AMOUNT;
        }
        if (delta) {
          let sum = [0, 0];
          let count = 0;
          for (const entityID of selectedIDs) {
            const entity = graph.hasEntity(entityID);
            if (!entity)
              continue;
            for (const part of graph.geometry(entity).parts) {
              const centroid = part.world?.centroid;
              if (!centroid)
                continue;
              sum = vecAdd(sum, centroid);
              count++;
            }
          }
          if (!count)
            return;
          const pivot = vecScale(sum, 1 / count);
          operation = new RotateOperation(context, selectedIDs);
          action = actionRotate(selectedIDs, pivot, delta);
        }
      } else if (["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(e.key)) {
        e.preventDefault();
        const MOVE_AMOUNT = 3;
        let delta;
        if (e.key === "ArrowLeft") {
          delta = [-MOVE_AMOUNT, 0];
        } else if (e.key === "ArrowRight") {
          delta = [MOVE_AMOUNT, 0];
        } else if (e.key === "ArrowUp") {
          delta = [0, -MOVE_AMOUNT];
        } else if (e.key === "ArrowDown") {
          delta = [0, MOVE_AMOUNT];
        }
        if (delta) {
          const t = viewport.transform;
          if (t.r) {
            delta = vecRotate(delta, -t.r, [0, 0]);
          }
          const k = Math.pow(2, t.z);
          const worldDelta = vecScale(delta, 1 / k);
          operation = new MoveOperation(context, selectedIDs);
          action = actionMove(selectedIDs, worldDelta);
        }
      }
      if (operation && action) {
        if (!operation.available())
          return;
        if (operation.disabled()) {
          ui?.Flash.show({
            duration: 4000,
            iconName: `#rapid-operation-${operation.id}`,
            iconClass: "operation disabled",
            label: operation.tooltip()
          });
          return;
        }
        const label = operation.editLabel();
        const props = { ...label, selectionAfter: selectedIDs };
        editor.perform(action);
        if (isSameSelection && editor.getUndoEdit()?.isLabeled(label)) {
          editor.commitAppend(props);
        } else {
          editor.commit(props);
        }
        this._setupOperations();
      }
    }
    _merge(newIDs) {
      if (!(newIDs instanceof Set))
        return;
      let needsRefresh = false;
      for (const entityID of this._osmIDs) {
        if (newIDs.has(entityID)) {
          needsRefresh = true;
          break;
        }
      }
      if (needsRefresh) {
        this._setupOperations();
      }
    }
    _setupOperations() {
      const context = this.context;
      const ui = context.systems.ui;
      for (const operation of this.operations) {
        operation.behavior?.disable();
      }
      this.operations = [];
      if (this._isAllOsm()) {
        const entityIDs = this._osmIDs.slice();
        const order = {
          copy: 1,
          downgrade: 2,
          delete: 3
        };
        this.operations = [...operations.available.values()].map((Op) => new Op(context, entityIDs)).filter((op) => op.available()).sort((a, b) => {
          const aOrder = order[a.id] || 0;
          const bOrder = order[b.id] || 0;
          return aOrder - bOrder;
        });
        for (const operation of this.operations) {
          operation.behavior?.enable();
        }
      }
      ui?.redrawEditMenu();
    }
    _chooseParentWay(entity) {
      if (!entity)
        return;
      const context = this.context;
      const editor = context.systems.editor;
      const graph = editor.staging.graph;
      if (entity.type === "way") {
        this._focusedParentID = entity.id;
      } else {
        const parentIDs = graph.parentWays(entity).map((way) => way.id);
        if (!parentIDs.length) {
          this._focusedParentID = null;
        } else {
          if (!this._focusedParentID || !parentIDs.includes(this._focusedParentID)) {
            this._focusedParentID = parentIDs[0];
          }
        }
      }
      return this._focusedParentID ? graph.hasEntity(this._focusedParentID) : undefined;
    }
    _firstVertex(e) {
      e.preventDefault();
      const way = this._chooseParentWay(this._singularDatum);
      if (!way)
        return;
      const context = this.context;
      const editor = context.systems.editor;
      const map = context.systems.map;
      const graph = editor.staging.graph;
      const nodeID = way.first();
      if (!nodeID)
        return;
      const node = graph.hasEntity(nodeID);
      if (!node)
        return;
      context.enter("select", { selection: [nodeID] });
      map.centerEase(node.loc);
    }
    _lastVertex(e) {
      e.preventDefault();
      const way = this._chooseParentWay(this._singularDatum);
      if (!way)
        return;
      const context = this.context;
      const editor = context.systems.editor;
      const map = context.systems.map;
      const graph = editor.staging.graph;
      const nodeID = way.last();
      if (!nodeID)
        return;
      const node = graph.hasEntity(nodeID);
      if (!node)
        return;
      context.enter("select", { selection: [nodeID] });
      map.centerEase(node.loc);
    }
    _previousVertex(e) {
      e.preventDefault();
      const entity = this._singularDatum;
      if (entity?.type !== "node")
        return;
      const way = this._chooseParentWay(this._singularDatum);
      if (!way)
        return;
      const currIndex = way.nodes.indexOf(entity.id);
      let nextIndex = -1;
      if (currIndex > 0) {
        nextIndex = currIndex - 1;
      } else if (way.isClosed()) {
        nextIndex = way.nodes.length - 2;
      }
      if (nextIndex !== -1) {
        const context = this.context;
        const editor = context.systems.editor;
        const map = context.systems.map;
        const graph = editor.staging.graph;
        const nodeID = way.nodes[nextIndex];
        if (!nodeID)
          return;
        const node = graph.hasEntity(nodeID);
        if (!node)
          return;
        context.enter("select", { selection: [node.id] });
        map.centerEase(node.loc);
      }
    }
    _nextVertex(e) {
      e.preventDefault();
      const entity = this._singularDatum;
      if (entity?.type !== "node")
        return;
      const way = this._chooseParentWay(this._singularDatum);
      if (!way)
        return;
      const currIndex = way.nodes.indexOf(entity.id);
      let nextIndex = -1;
      if (currIndex < way.nodes.length - 1) {
        nextIndex = currIndex + 1;
      } else if (way.isClosed()) {
        nextIndex = 0;
      }
      if (nextIndex !== -1) {
        const context = this.context;
        const editor = context.systems.editor;
        const map = context.systems.map;
        const graph = editor.staging.graph;
        const nodeID = way.nodes[nextIndex];
        if (!nodeID)
          return;
        const node = graph.hasEntity(nodeID);
        if (!node)
          return;
        context.enter("select", { selection: [node.id] });
        map.centerEase(node.loc);
      }
    }
    _focusNextParent(e) {
      e.preventDefault();
      const entity = this._singularDatum;
      if (entity?.type !== "node")
        return;
      const context = this.context;
      const editor = context.systems.editor;
      const graph = editor.staging.graph;
      const parentIDs = graph.parentWays(entity).map((way) => way.id);
      if (parentIDs.length) {
        const currIndex = this._focusedParentID ? parentIDs.indexOf(this._focusedParentID) : -1;
        let nextIndex = currIndex + 1;
        if (nextIndex >= parentIDs.length) {
          nextIndex = 0;
        }
        this._focusedParentID = parentIDs[nextIndex];
      }
    }
    _selectParentWays() {
      const context = this.context;
      const editor = context.systems.editor;
      const graph = editor.staging.graph;
      const parentWayIDs = new Set;
      for (const entityID of this._osmIDs) {
        const entity = graph.hasEntity(entityID);
        if (entity?.type !== "node")
          continue;
        for (const way of graph.parentWays(entity)) {
          parentWayIDs.add(way.id);
        }
      }
      if (!parentWayIDs.size)
        return;
      context.enter("select", {
        selection: [...parentWayIDs],
        focusedParentID: this._focusedParentID ?? undefined
      });
    }
    _selectChildNodes() {
      const context = this.context;
      const editor = context.systems.editor;
      const graph = editor.staging.graph;
      const childNodeIDs = new Set;
      for (const entityID of this._osmIDs) {
        const entity = graph.hasEntity(entityID);
        if (entity?.type !== "way")
          continue;
        for (const nodeID of entity.nodes) {
          childNodeIDs.add(nodeID);
        }
      }
      if (!childNodeIDs.size)
        return;
      context.enter("select", {
        selection: [...childNodeIDs],
        focusedParentID: this._focusedParentID ?? undefined
      });
    }
    _hover(eventData) {
      const context = this.context;
      const editor = context.systems.editor;
      const eventManager = context.systems.gfx.eventManager;
      const graph = editor.staging.graph;
      const target = eventData.target;
      const dataID = target?.dataID;
      if (!dataID)
        return;
      const entity = graph.hasEntity(dataID);
      let geom = entity?.geometry(graph) ?? "other";
      if (!entity && target.data?.type === "midpoint") {
        geom = "midpoint";
      }
      switch (geom) {
        case "area":
          eventManager.setCursor("areaCursor");
          break;
        case "line":
          eventManager.setCursor("lineCursor");
          break;
        case "point":
          eventManager.setCursor("pointCursor");
          break;
        case "midpoint":
          eventManager.setCursor("selectSplitCursor");
          break;
        case "vertex":
          eventManager.setCursor("vertexCursor");
          break;
        default:
          eventManager.setCursor("grab");
          break;
      }
    }
  }

