  // modules/services/TaginfoService.ts
  var TAGINFO_API = "https://taginfo.openstreetmap.org/api/4/";
  var tag_sorts = {
    point: "count_nodes",
    vertex: "count_nodes",
    area: "count_ways",
    line: "count_ways"
  };
  var tag_sort_members = {
    point: "count_node_members",
    vertex: "count_node_members",
    area: "count_way_members",
    line: "count_way_members",
    relation: "count_relation_members"
  };
  var tag_filters = {
    point: "nodes",
    vertex: "nodes",
    area: "ways",
    line: "ways"
  };
  var tag_members_fractions = {
    point: "count_node_members_fraction",
    vertex: "count_node_members_fraction",
    area: "count_way_members_fraction",
    line: "count_way_members_fraction",
    relation: "count_relation_members_fraction"
  };

  class TaginfoService extends AbstractSystem {
    _cache;
    _popularKeys;
    constructor(context) {
      super(context);
      this.id = "taginfo";
      this.requiredDependencies = new Set(["network"]);
      this.optionalDependencies = new Set(["l10n", "scheduler"]);
      this._cache = {};
      this._popularKeys = {
        postal_code: true,
        full_name: true,
        loc_name: true,
        reg_name: true,
        short_name: true,
        sorting_name: true,
        artist_name: true,
        nat_name: true,
        long_name: true,
        "bridge:name": true
      };
      this.keys = this.keys.bind(this);
      this.multikeys = this.multikeys.bind(this);
      this.values = this.values.bind(this);
      this.roles = this.roles.bind(this);
      this.docs = this.docs.bind(this);
      this._request = this._request.bind(this);
    }
    initAsync() {
      return super.initAsync();
    }
    startAsync() {
      if (this._startPromise)
        return this._startPromise;
      const l10n = this.context.systems.l10n;
      const langCode = l10n?.languageCode || "en";
      const params = {
        rp: 100,
        sortname: "values_all",
        sortorder: "desc",
        page: 1,
        debounce: false,
        lang: langCode
      };
      return this._startPromise = new Promise((resolve, reject) => {
        this.keys(params, (err, results) => {
          if (err) {
            this._startPromise = null;
            reject();
          } else {
            for (const d of results) {
              if (d.value === "opening_hours")
                continue;
              this._popularKeys[d.value] = true;
            }
            this._started = true;
            resolve();
          }
        });
      });
    }
    resetAsync() {
      const context = this.context;
      const network = context.systems.network;
      const scheduler = context.systems.scheduler;
      scheduler?.cancel("taginfo-request");
      network.clearMatching((id) => id.includes(TAGINFO_API));
      return Promise.resolve();
    }
    keys(params, callback) {
      const context = this.context;
      const l10n = context.systems.l10n;
      const scheduler = context.systems.scheduler;
      const langCode = l10n?.languageCode || "en";
      const shouldDebounce = params.debounce;
      params = this._clean(this._setSort(params));
      params = Object.assign({
        rp: 10,
        sortname: "count_all",
        sortorder: "desc",
        page: 1,
        lang: langCode
      }, params);
      const url = TAGINFO_API + "keys/all?" + utilQsString(params, false);
      const request = () => this._request(url, params, false, callback, (err, result) => {
        if (err) {
          callback(err);
        } else {
          const f = this._filterKeys(params.filter);
          const vals = result.data.filter(f).sort(this._sortKeys).map(this._valKey);
          this._cache[url] = vals;
          callback(null, vals);
        }
      });
      if (shouldDebounce && scheduler) {
        scheduler.debounce("taginfo-request", request, { ms: 300 });
      } else {
        request();
      }
    }
    multikeys(params, callback) {
      const context = this.context;
      const l10n = context.systems.l10n;
      const scheduler = context.systems.scheduler;
      const langCode = l10n?.languageCode || "en";
      const shouldDebounce = params.debounce;
      params = this._clean(this._setSort(params));
      params = Object.assign({
        rp: 25,
        sortname: "count_all",
        sortorder: "desc",
        page: 1,
        lang: langCode
      }, params);
      const prefix = params.query ?? "";
      const url = TAGINFO_API + "keys/all?" + utilQsString(params, false);
      const request = () => this._request(url, params, true, callback, (err, result) => {
        if (err) {
          callback(err);
        } else {
          const f = this._filterMultikeys(prefix);
          const vals = result.data.filter(f).map(this._valKey);
          this._cache[url] = vals;
          callback(null, vals);
        }
      });
      if (shouldDebounce && scheduler) {
        scheduler.debounce("taginfo-request", request, { ms: 300 });
      } else {
        request();
      }
    }
    values(params, callback) {
      const key = params.key;
      if (key && this._popularKeys[key]) {
        callback(null, []);
        return;
      }
      const context = this.context;
      const l10n = context.systems.l10n;
      const scheduler = context.systems.scheduler;
      const langCode = l10n?.languageCode || "en";
      const shouldDebounce = params.debounce;
      params = this._clean(this._setSort(this._setFilter(params)));
      params = Object.assign({
        rp: 25,
        sortname: "count_all",
        sortorder: "desc",
        page: 1,
        lang: langCode
      }, params);
      const url = TAGINFO_API + "key/values?" + utilQsString(params, false);
      const request = () => this._request(url, params, false, callback, (err, result) => {
        if (err) {
          callback(err);
        } else {
          const re = /network|taxon|genus|species|brand|grape_constiety|royal_cypher|listed_status|booth|rating|stars|:output|_hours|_times|_ref|manufacturer|country|target|brewery/;
          const allowUpperCase = re.test(params.key ?? "");
          const f = this._filterValues(allowUpperCase);
          const vals = result.data.filter(f).map(this._valKeyDescription);
          this._cache[url] = vals;
          callback(null, vals);
        }
      });
      if (shouldDebounce && scheduler) {
        scheduler.debounce("taginfo-request", request, { ms: 300 });
      } else {
        request();
      }
    }
    roles(params, callback) {
      const context = this.context;
      const l10n = context.systems.l10n;
      const scheduler = context.systems.scheduler;
      const langCode = l10n?.languageCode || "en";
      const shouldDebounce = params.debounce;
      const geometry = params.geometry ?? "";
      params = this._clean(this._setSortMembers(params));
      params = Object.assign({
        rp: 25,
        sortname: "count_all_members",
        sortorder: "desc",
        page: 1,
        lang: langCode
      }, params);
      const url = TAGINFO_API + "relation/roles?" + utilQsString(params, false);
      const request = () => this._request(url, params, true, callback, (err, result) => {
        if (err) {
          callback(err);
        } else {
          const f = this._filterRoles(geometry);
          const vals = result.data.filter(f).map(this._roleKey);
          this._cache[url] = vals;
          callback(null, vals);
        }
      });
      if (shouldDebounce && scheduler) {
        scheduler.debounce("taginfo-request", request, { ms: 300 });
      } else {
        request();
      }
    }
    docs(params, callback) {
      const context = this.context;
      const scheduler = context.systems.scheduler;
      const shouldDebounce = params.debounce;
      params = this._clean(this._setSort(params));
      let path = "key/wiki_pages?";
      if (params.value) {
        path = "tag/wiki_pages?";
      } else if (params.rtype) {
        path = "relation/wiki_pages?";
      }
      const url = TAGINFO_API + path + utilQsString(params, false);
      const request = () => this._request(url, params, true, callback, (err, result) => {
        if (err) {
          callback(err);
        } else {
          this._cache[url] = result.data;
          callback(null, result.data);
        }
      });
      if (shouldDebounce && scheduler) {
        scheduler.debounce("taginfo-request", request, { ms: 300 });
      } else {
        request();
      }
    }
    _sets(params, n, o) {
      if (params.geometry && o[params.geometry]) {
        params[n] = o[params.geometry];
      }
      return params;
    }
    _setFilter(params) {
      return this._sets(params, "filter", tag_filters);
    }
    _setSort(params) {
      return this._sets(params, "sortname", tag_sorts);
    }
    _setSortMembers(params) {
      return this._sets(params, "sortname", tag_sort_members);
    }
    _clean(params) {
      return utilObjectOmit(params, ["geometry", "debounce"]);
    }
    _filterKeys(type) {
      const count_type = type ? "count_" + type : "count_all";
      return (d) => parseFloat(d[count_type]) > 2500 || d.in_wiki;
    }
    _filterMultikeys(prefix) {
      return (d) => {
        const re = new RegExp("^" + prefix + "(.*)$");
        const matches = d.key.match(re) || [];
        return matches.length === 2 && matches[1].indexOf(":") === -1;
      };
    }
    _filterValues(allowUpperCase) {
      return (d) => {
        if (d.value.match(/[;,]/) !== null)
          return false;
        if (!allowUpperCase && d.value.match(/[A-Z*]/) !== null)
          return false;
        return parseFloat(d.fraction) > 0;
      };
    }
    _filterRoles(geometry) {
      return (d) => {
        if (d.role === "")
          return false;
        if (d.role.match(/[A-Z*;,]/) !== null)
          return false;
        if (geometry === "")
          return true;
        return parseFloat(d[tag_members_fractions[geometry]]) > 0;
      };
    }
    _valKey(d) {
      return {
        value: d.key,
        title: d.key
      };
    }
    _valKeyDescription(d) {
      const obj = {
        value: d.value,
        title: d.description || d.value
      };
      if (d.count) {
        obj.count = d.count;
      }
      return obj;
    }
    _roleKey(d) {
      return {
        value: d.role,
        title: d.role
      };
    }
    _sortKeys(a, b) {
      return a.key.indexOf(":") === -1 && b.key.indexOf(":") !== -1 ? -1 : a.key.indexOf(":") !== -1 && b.key.indexOf(":") === -1 ? 1 : 0;
    }
    _request(url, params, exactMatch, callback, loaded) {
      if (this._checkCache(url, params, exactMatch, callback))
        return;
      const network = this.context.systems.network;
      network.fetch(url).then((result) => {
        if (loaded)
          loaded(null, result);
      }).catch((err) => {
        if (err.name === "AbortError")
          return;
        if (loaded)
          loaded(err.message);
      });
    }
    _checkCache(url, params, exactMatch, callback) {
      const rp = params.rp ?? 25;
      let testQuery = params.query ?? "";
      let testUrl = url;
      do {
        const hit = this._cache[testUrl];
        if (hit && (url === testUrl || hit.length < rp)) {
          callback(null, hit);
          return true;
        }
        if (exactMatch || !testQuery.length)
          return false;
        testQuery = testQuery.slice(0, -1);
        testUrl = url.replace(/&query=(.*?)&/, `&query=${testQuery}&`);
      } while (testQuery.length >= 0);
      return false;
    }
  }

  // modules/services/WaybackService.ts
